<?php
namespace App\Models; use App\Models\Concerns\InvalidatesWorkProcesses; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class WorkProcessStage extends Model { use InvalidatesWorkProcesses; protected $fillable=['work_process_id','title','description','icon','duration_text','display_order','is_active']; protected function casts():array{return ['is_active'=>'boolean'];} public function workProcess():BelongsTo{return $this->belongsTo(WorkProcess::class);} public function deliverables():HasMany{return $this->hasMany(WorkProcessDeliverable::class)->orderBy('display_order');} }
